<?php
require __DIR__.'/../config/app.php';
$me=require_role('admin');
$action=(string)($_GET['action']??'');$id=(int)($_GET['id']??0);$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
    csrf_check();
    try{
        if(($_POST['delete']??'')==='1'){
            db()->prepare('DELETE FROM events WHERE id=?')->execute([(int)$_POST['id']]);
            flash('Event deleted.');
        }else{
            $data=[trim((string)($_POST['title']??'')),strtolower((string)($_POST['category']??'')),trim((string)($_POST['description']??'')),(string)($_POST['event_date']??''),(string)($_POST['event_time']??'09:00'),trim((string)($_POST['venue']??'')),(int)($_POST['capacity']??100),(int)($_POST['is_published']??0)];
            if((int)($_POST['id']??0)){$data[]=(int)$_POST['id'];db()->prepare('UPDATE events SET title=?,category=?,description=?,event_date=?,event_time=?,venue=?,capacity=?,is_published=? WHERE id=?')->execute($data);flash('Event updated.');}
            else{db()->prepare('INSERT INTO events(title,category,description,event_date,event_time,venue,capacity,is_published) VALUES(?,?,?,?,?,?,?,?)')->execute($data);flash('Event created.');}
        }
        go('admin/events.php');
    }catch(Throwable $t){$error='Could not save the event. Check the required fields and database setup.';}
}
$search=trim((string)($_GET['q']??''));$categoryFilter=(string)($_GET['category']??'');$events=[];try{$sql='SELECT e.*,(SELECT COUNT(*) FROM event_applications a WHERE a.event_id=e.id) applicants FROM events e WHERE (?=\'\' OR e.title LIKE ? OR e.venue LIKE ?) AND (?=\'\' OR e.category=?) ORDER BY CASE WHEN e.event_date>=? THEN 0 ELSE 1 END,e.event_date ASC,e.event_time ASC';$term='%'.$search.'%';$q=db()->prepare($sql);$q->execute([$search,$term,$term,$categoryFilter,$categoryFilter,date('Y-m-d')]);$events=$q->fetchAll();}catch(Throwable $t){}if(($_GET['export']??'')==='csv'){header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="eventhub-events-'.date('Ymd').'.csv"');$out=fopen('php://output','w');fputcsv($out,['Event','Category','Date','Time','Venue','Capacity','Applications','Status']);foreach($events as $ev)fputcsv($out,[$ev['title'],$ev['category'],$ev['event_date'],$ev['event_time'],$ev['venue'],$ev['capacity'],$ev['applicants'],$ev['is_published']?'Published':'Draft']);fclose($out);exit;}
$perPage=25;$totalRecords=count($events);$totalPages=(int)ceil($totalRecords/$perPage);$currentPage=max(1,min($totalPages?:1,(int)($_GET['page']??1)));$events=array_slice($events,($currentPage-1)*$perPage,$perPage);$event=null;if($id){$q=db()->prepare('SELECT * FROM events WHERE id=?');$q->execute([$id]);$event=$q->fetch();}
$editing=$action==='create'||$action==='edit';$pageTitle=$editing?($action==='edit'?'Edit Event':'Add Event'):'Manage Events';$bodyClass='dashboard-page admin-page';$activePage='events';
require __DIR__.'/../includes/header.php';
?><div class="dash-layout admin-layout"><?php require __DIR__.'/../includes/sidebar.php';?><main class="content-page admin-content admin-events-page"><header class="admin-page-heading"><div><span class="admin-eyebrow">EVENT MANAGEMENT</span><h1><?=$editing?e($pageTitle):'Manage Events'?></h1><p><?=$editing?'Create or update an event for the Marwadi University community.':'Create, update and publish campus events from one place.'?></p></div><?php if(!$editing):?><a class="btn primary" href="<?=url('admin/events.php?action=create')?>">Add Event</a><?php endif;?></header><?php require __DIR__.'/event-nav.php';?><?php if(!$editing):?><section class="admin-work-card"><form method="get" class="admin-report-filters"><input name="q" value="<?=e($search)?>" placeholder="Search event or venue"><select name="category"><option value="">All categories</option><?php foreach(['cultural','technical','sports','volunteer'] as $c):?><option value="<?=$c?>" <?=$categoryFilter===$c?'selected':''?>><?=ucfirst($c)?></option><?php endforeach;?></select><button class="btn primary">Filter</button><a class="btn outline" href="<?=url('admin/events.php?'.http_build_query(['q'=>$search,'category'=>$categoryFilter,'export'=>'csv']))?>">Export CSV</a></form></section><?php endif;?><?php if($error):?><div class="inline-error"><?=e($error)?></div><?php endif;?><?php if($editing):?><section class="admin-work-card"><div class="admin-card-heading"><span class="admin-heading-icon"><?=eventhub_icon('calendar')?></span><div><h2>Event details</h2><p>Fill in the event information below.</p></div></div><form method="post" class="form-card admin-event-form"><input type="hidden" name="_csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=e((string)($event['id']??''))?>"><div class="admin-form-grid"><label>Event name<input required maxlength="190" name="title" value="<?=e($event['title']??'')?>" placeholder="e.g. Inter-College Cultural Fest"></label><label>Category<select name="category"><?php foreach(['cultural','technical','sports','volunteer'] as $c):?><option value="<?=$c?>" <?=($event['category']??'')===$c?'selected':''?>><?=ucfirst($c)?></option><?php endforeach;?></select></label><label>Date<input type="date" required name="event_date" value="<?=e($event['event_date']??'')?>"></label><label>Start time<input type="time" name="event_time" value="<?=e($event['event_time']??'09:00')?>"></label><label>Venue<input required maxlength="190" name="venue" value="<?=e($event['venue']??'')?>" placeholder="Campus location"></label><label>Capacity<input type="number" min="0" name="capacity" value="<?=e((string)($event['capacity']??100))?>"></label><label class="admin-form-wide">Description<textarea name="description" rows="4" placeholder="Tell students what to expect..."><?=e($event['description']??'')?></textarea></label></div><div class="admin-form-actions"><label class="check-label"><input type="checkbox" name="is_published" value="1" <?=!isset($event['is_published'])||$event['is_published']?'checked':''?>> Publish this event</label><div><a class="btn outline" href="<?=url('admin/events.php')?>">Cancel</a> <button class="btn primary" type="submit">Save Event</button></div></div></form></section><?php else:?><section class="admin-work-card"><div class="admin-card-heading"><span class="admin-heading-icon"><?=eventhub_icon('calendar')?></span><div><h2>All events <span class="admin-count"><?=count($events)?></span></h2><p>Review event details, publication status and applications.</p></div></div><div class="table-wrap admin-table-wrap"><table><thead><tr><th>Event</th><th>Category</th><th>Date</th><th>Venue</th><th>Applications</th><th>State</th><th>Actions</th></tr></thead><tbody><?php foreach($events as $ev):?><tr><td><strong><?=e($ev['title'])?></strong></td><td><span class="pill <?=e($ev['category'])?>"><?=e(ucfirst($ev['category']))?></span></td><td><?=date('d M Y',strtotime($ev['event_date']))?></td><td><?=e($ev['venue'])?></td><td><?=(int)$ev['applicants']?></td><td><span class="admin-state <?=$ev['is_published']?'published':'draft'?>"><?=$ev['is_published']?'Published':'Draft'?></span></td><td><div class="admin-row-actions"><a href="<?=url('admin/events.php?action=edit&id='.$ev['id'])?>">Edit</a><form class="inline-form" method="post" onsubmit="return confirm('Delete this event and its applications and saved interests? Related cultural activities remain. This cannot be undone.')"><input type="hidden" name="_csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$ev['id']?>"><input type="hidden" name="delete" value="1"><button class="text-button">Delete</button></form></div></td></tr><?php endforeach;?></tbody></table></div><?php if(!$events):?><div class="empty">No events yet. Add your first event to get started.</div><?php endif;?></section><?php endif;?><?php if(!$editing)require __DIR__.'/../includes/admin-pagination.php';?></main></div><?php require __DIR__.'/../includes/footer.php';

